def transform(grid):
    h = len(grid) // 4
    out = [row[:] for row in grid[:h]]
    # Overlay the lower three color layers into holes in the top layer.
    for r in range(h):
        for c in range(len(out[r])):
            if out[r][c] == 0:
                for layer in range(1, 4):
                    v = grid[layer*h + r][c]
                    if v:
                        out[r][c] = v
                        break
    return out
